mapper.select:
SELECT resource_type AS type, COUNT(1) AS count FROM moral_resource WHERE deleted = 0
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY resource_type

SELECT status AS status, COUNT(1) AS count FROM moral_resource WHERE deleted = 0
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY status

SELECT DATE_FORMAT(create_time, '%Y-%m') AS date, COUNT(1) AS count FROM moral_resource WHERE deleted = 0
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m')

SELECT DATE_FORMAT(create_time, '%Y-%m') AS date, ROUND(AVG(learn_rate),2) AS rate FROM moral_resource WHERE deleted = 0
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m')

SELECT DATE_FORMAT(create_time, '%Y-%m') AS date, ROUND(AVG(learn_rate),2) AS rate FROM moral_resource WHERE deleted = 0
AND resource_type = #{resourceType}
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m')

SELECT resource_type AS type, COUNT(1) AS count FROM moral_resource WHERE deleted = 0
AND resource_type = #{resourceType}
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY resource_type
